#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){int N=argc>1?atoi(argv[1]):11;for(int n=1;n<=N;n++){vector<int> a(n);iota(a.begin(),a.end(),1);long long total=0,patterns[6]={0},up=0, lastup=0, firstup=0;do{bool good=true;int v321=0,v213=0,v231=0,asc=0;for(int i=0;i<n-1;i++)asc+=a[i]<a[i+1];for(int i=0;i<n-2;i++){int x=a[i],y=a[i+1],z=a[i+2];if((x<y&&y<z)||(x<z&&z<y)||(y<z&&z<x)){good=false;break;} if(y<x&&x<z)v213++;else if(z<x&&x<y)v231++;else if(z<y&&y<x)v321++; else {cerr<<"unknown";exit(1);}}if(good){total++;patterns[0]+=v213;patterns[1]+=v231;patterns[2]+=v321;up+=asc;if(n>1){firstup+=a[0]<a[1];lastup+=a[n-2]<a[n-1];}}}while(next_permutation(a.begin(),a.end()));cout<<n<<" "<<total<<" "<<patterns[0]<<" "<<patterns[1]<<" "<<patterns[2]<<" asc="<<up<<" first="<<firstup<<" last="<<lastup<<" prop321="<<setprecision(9)<<(n>=3?double(patterns[2])/(n*total):0)<<"\n";}}
